def renew_worker(reservation, args):
    """盯一条预约对应的机器，释放后按原卡数/原时长续订。"""
    gpus = reservation.get("gpus", [])
    if not gpus:
        log(f"renew: reservation {reservation['id']} has no gpus, skip")
        return
    host = gpu_host(gpus[0])
    hours = (parse_ts(reservation["end_time"]) - parse_ts(reservation["start_time"])).total_seconds() / 3600
    ns = argparse.Namespace(
        vendor=None, model=None, host=host, count=len(gpus), same_machine=False,
        hours=hours, interval=args.interval,
        do_not_kill=reservation.get("importance") == "do_not_kill",
        description=f"auto-renew of {reservation['id']}",
