    log(f"renew: watching {host} ({len(gpus)} GPUs, {hours:g}h) for reservation {reservation['id']}")
    while True:
        found = find_free(ns)
        if found:
            try:
                create_reservation(found, ns)
                return
            except SystemExit as e:
                msg = str(e)
                m = re.search(r"would be (\d+)h .* max is (\d+)h", msg)
                if m:
                    over = int(m.group(1)) - int(m.group(2))
                    ns.hours -= over
                    if ns.hours >= 1:
                        log(f"renew: quota exceeded by {over}h, retrying with hours={ns.hours:g}")
                        continue
                    log("renew: no daily quota left (allowed < 1h), giving up")
                    return
                log(f"renew: booking failed ({msg}), retrying in {ns.interval}s...")
        time.sleep(ns.interval)


def cmd_renew(args):
    """监控名下活跃预约，到期前 --before 分钟起尝试按原配置续订同一台机器。"""
