    log(f"START renew watcher: before={args.before}min interval={args.interval}s")
    seen = set()  # 已触发续订的 reservation id
    while True:
        try:
            reservations = api("GET", "/api/v1/reservations",
                               params={"user_id": me["id"], "status": "active"})
        except SystemExit as e:
            log(f"renew: failed to list reservations ({e}), retrying...")
            time.sleep(args.interval)
            continue
        now = datetime.now(timezone.utc)
        for r in reservations:
            if r["id"] in seen:
                continue
            try:
                end = parse_ts(r["end_time"])
