            left = (end - now).total_seconds() / 60
            if left <= args.before:
                seen.add(r["id"])
                log(f"renew: reservation {r['id']} ends in {left:.0f}min, starting renew worker")
                threading.Thread(target=renew_worker, args=(r, args), daemon=True).start()
        time.sleep(60)"}

