            kv = {}
            for line in f:
                line = line.strip()
                if "=" in line:
                    k, v = line.split("=", 1)
                    kv[k.strip().lower()] = v.strip()
        return kv.get("user"), kv.get("password")
    except OSError:
        return None, None


